import{z as o,x as s,o as a,c as p,q as B,j as t,D as E,d as A,s as r,S as i,b as l}from"./chunks/framework.C8m1ZpeB.js";const C=JSON.parse('{"title":"反思机制的设计","description":"","frontmatter":{"title":"反思机制的设计","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/pl-reflection-design.md","filePath":"llm/pl-reflection-design.md","lastUpdated":1791413859000}'),d={name:"llm/pl-reflection-design.md"};function D(F,e,m,f,h,c){const n=s("Mermaid");return a(),p("div",null,[e[2]||(e[2]=B('<h1 id="反思机制的设计" tabindex="-1">反思机制的设计 <a class="header-anchor" href="#反思机制的设计" aria-label="Permalink to &quot;反思机制的设计&quot;">​</a></h1><div class="epigraph"><p>「再想想」若不改变答案，就是把同一句话再说一遍；反思的设计问题不是要不要想，而是何时触发、写什么、何时停。</p><footer>—— 据 Shinn et al., Reflexion, NeurIPS 2023；Madaan et al., Self-Refine, 2023；DeepSeek-AI, DeepSeek-R1, 2025 整理</footer></div><p><a href="/llm/pl-process-supervision-inference">上一课</a>把树上的剪枝交给外部 PRM：分数硬，但要多养一个打分模型，且开放域没有可靠的逐步真值。没有 PRM、预算也买不起一棵树时，唯一剩下的是链内的自我修正。本课写反思机制的设计——触发条件、反思内容、轮数预算与停止判据，覆盖回合内的<a href="/llm/self-verification-backtrack">自我验证与回溯</a>与跨回合的 <a href="/llm/reflexion">Reflexion</a> 两种形态；它们的机制基础不重讲。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>链写错后让模型「再想想」，最常见的结局是复读：同样的假设、同样的算式、同样的死路，只是换了措辞。原因是反思被当成一句咒语，而不是一次有输入的计算。设计要回答四件事：<strong>何时触发</strong>——无条件反思既浪费也是<a href="/llm/overthinking">过度思考</a>的来源；<strong>写什么</strong>——「我应该更认真」没有可执行约束，下一回合条件于它只会再错一遍；<strong>花多少</strong>——反思本身是 token，没有上限就可能在错误方向上无限深挖；<strong>怎么停</strong>——没有判据，「再想一次」永远成立。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>触发器按成本排序：终局校验失败（答案解析不出、单测挂、格式不符）最便宜最硬；外部检测器报警次之；上一课 PRM 的门控接点是第三种——分数跌破阈值或停滞即触发；预算过半仍无候选解是兜底。四条都过而未触发，就不该反思，直接返回。</p><p>反思内容必须是结构化的三条：错误签名（哪一步、什么类型的错）、禁区清单（已试路径的否定式列表）、待检步骤（下一轮先核对什么）。Reflexion 的跨回合形态再加一条管线：评估器判定成败，生成口头反思写入记忆，下一回合条件于这段话重试；观察是环境即时返回，反思是跨尝试的元文本，两槽必须分开，且记忆是文本就可能被环境内容污染，要当不可信输入对待。</p><p><span class="marginnote">「错误签名」与「禁区清单」翻译成大白话：签名是给这次错误办一张身份证——「第 3 步，把减法当成了加法」；禁区是已踩过坑的黑名单——「不要再假设单价是 8」。下一轮开始前先查这两张表，等于强迫模型带着案底重审，而不是换个措辞把同一条死路再走一遍。</span></p><p><span class="marginnote">判别有用回溯与空转的唯一口径是答案翻转率：翻转后正确率上升才是修正，翻转后仍错是换了姿势的错，不翻转是复读。监控按翻转率分桶，不要只看反思字数。</span></p><p>轮数预算：反思最多 \\(k\\) 轮（经验上小常数），连续两轮答案不变且禁区不变即停——那是在复读。每轮的产物必须改变下一轮的条件：新禁区、新假设或新校验通过，三者皆无则终止并归档失败原因。</p><p><span class="marginnote">数字实例（示意）：取 \\(k=2\\)，一次请求最坏是 3 次尝试加 2 段反思；设每段反思约 500 token、每次尝试 2000 token，账单上限约 7000 token，花得完也说得清。若不设 \\(k\\)，难题上滚出十几个「再想想」并不罕见——token 翻数倍，答案翻转率却几乎为零，这就是过度思考的最常见长相。</span></p>',12)),(a(),t(i,null,{default:E(()=>[r(n,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20TRY%5B%22%E7%AC%AC%20n%20%E8%BD%AE%E5%B0%9D%E8%AF%95%22%5D%20--%3E%20CHK%5B%22%E6%A0%A1%E9%AA%8C%EF%BC%9A%E7%BB%88%E5%B1%80%20%2F%20%E6%A3%80%E6%B5%8B%E5%99%A8%20%2F%20%E5%88%86%E6%95%B0%E9%97%A8%E6%8E%A7%22%5D%0A%20%20CHK%20--%3E%20PASS%7B%22%E9%80%9A%E8%BF%87%3F%22%7D%0A%20%20PASS%20--%3E%7C%E6%98%AF%7C%20OUT%5B%22%E8%BF%94%E5%9B%9E%E7%AD%94%E6%A1%88%22%5D%0A%20%20PASS%20--%3E%7C%E5%90%A6%7C%20Q%7B%22%E8%BD%AE%E6%95%B0%E8%BE%BE%20k%20%E6%88%96%E8%BF%9E%E7%BB%AD%E6%97%A0%E6%96%B0%E4%BF%A1%E6%81%AF%3F%22%7D%0A%20%20Q%20--%3E%7C%E6%98%AF%7C%20FAIL%5B%22%E8%BE%93%E5%87%BA%E5%A4%B1%E8%B4%A5%E5%B9%B6%E5%BD%92%E5%9B%A0%E5%BD%92%E6%A1%A3%22%5D%0A%20%20Q%20--%3E%7C%E5%90%A6%7C%20REF%5B%22%E5%86%99%E5%8F%8D%E6%80%9D%EF%BC%9A%E9%94%99%E8%AF%AF%E7%AD%BE%E5%90%8D%20%2B%20%E7%A6%81%E5%8C%BA%E6%B8%85%E5%8D%95%22%5D%0A%20%20REF%20--%3E%20TRY%0A"})]),fallback:E(()=>[...e[0]||(e[0]=[A(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=l("h2",{id:"机制",tabindex:"-1"},[A("机制 "),l("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),e[4]||(e[4]=l("p",null,"反思是上下文内的条件化，不改权重；Reflexion 的「学习」随记忆的生命周期结束，清空记忆即清空进步。它能起作用的前提是触发信号携带真实信息：校验器说「挂了哪条测试」，反思才能归因到具体步骤；信号只有 0/1 时，归因多半是编故事——把系统锁进一条漂亮的错误叙事，比不反思更糟。这与上一课的结论同构：硬信号（校验器、单测）优先于软信号（自评、口头检查），反思只是消费信号的那一环，不能替代信号本身。",-1)),(a(),t(i,null,{default:E(()=>[r(n,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20SIG%7B%22%E8%BF%99%E4%B8%80%E8%BD%AE%E5%8F%8D%E6%80%9D%E6%8B%BF%E5%88%B0%E4%BA%86%E4%BB%80%E4%B9%88%E4%BF%A1%E5%8F%B7%22%7D%0A%20%20SIG%20--%3E%20HARD%5B%22%E7%A1%AC%E4%BF%A1%E5%8F%B7%EF%BC%9A%E5%8D%95%E6%B5%8B%E5%A4%B1%E8%B4%A5%20%2F%20%E8%A7%A3%E6%9E%90%E6%8A%A5%E9%94%99%22%5D%0A%20%20SIG%20--%3E%20SOFT%5B%22%E8%BD%AF%E4%BF%A1%E5%8F%B7%EF%BC%9A%E8%87%AA%E8%AF%84%E6%88%96%E5%8F%A3%E5%A4%B4%E6%A3%80%E6%9F%A5%22%5D%0A%20%20HARD%20--%3E%20ATTR%5B%22%E5%8F%AF%E5%BD%92%E5%9B%A0%E5%88%B0%E5%85%B7%E4%BD%93%E6%AD%A5%E9%AA%A4%22%5D%0A%20%20ATTR%20--%3E%20CHANGE%5B%22%E4%B8%8B%E8%BD%AE%E6%9D%A1%E4%BB%B6%E7%9C%9F%E8%A2%AB%E6%94%B9%E5%8F%98%22%5D%0A%20%20SOFT%20--%3E%20STORY%5B%22%E5%BD%92%E5%9B%A0%E5%A4%9A%E5%8D%8A%E5%9C%A8%E7%BC%96%E6%95%85%E4%BA%8B%22%5D%0A%20%20STORY%20--%3E%20LOCK%5B%22%E9%94%81%E8%BF%9B%E6%BC%82%E4%BA%AE%E7%9A%84%E9%94%99%E8%AF%AF%E5%8F%99%E4%BA%8B%22%5D%0A"})]),fallback:E(()=>[...e[1]||(e[1]=[A(" Loading... ",-1)])]),_:1})),e[5]||(e[5]=B('<p><span class="marginnote">「不改权重」的直觉类比：反思像把备忘写在便签上贴在屏幕边——模型本身没变聪明，下次会话把便签一撕（记忆清空），「进步」就归零。所以 Reflexion 的收益只在同一任务的多轮尝试里记账，别把它当成模型学会了什么；真要长期保留，得把便签誊进检索库，并防着便签本身被污染。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>易题上触发反思就是过度思考：按难度分桶看翻转率，简单桶直接关触发器。蒸馏可以模仿反思用语（「等等，再算一遍」），不复制纠错行为，别把语气当能力。评测必须用同等重试次数的无反思基线——多跑一轮本身就能涨点，增益只有超出这份基线才归给反思。开放域没有校验信号时，反思只能当格式整理器，别指望它纠正事实。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>反思四件套：触发条件、结构化内容（签名/禁区/待检）、轮数上限、停止判据，缺一就是复读或空转。</li><li>无条件触发是浪费；校验失败与门控报警才值得想。</li><li>答案翻转率是唯一硬口径；不翻转是复读，翻转仍错要归因而不是续想。</li><li>回合内自检与跨回合记忆分槽；记忆是不可信文本，要防注入。</li><li>评测用同等重试的无反思基线；蒸馏学得会语气，学不会纠错。</li><li>出处：Shinn et al., <em>Reflexion</em>, NeurIPS 2023；Madaan et al., <em>Self-Refine</em>, 2023；DeepSeek-AI, <em>DeepSeek-R1</em>, 2025。</li></ul>',5))])}const k=o(d,[["render",D]]);export{C as __pageData,k as default};
